import { NextResponse } from 'next/server';

type Params = {
  id: string;
};

type UpdatePostBody = {
  title?: string;
  content?: string;
};

type PostRecord = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
};

function parsePostId(id: string): number | null {
  const parsedId = Number.parseInt(id, 10);
  return Number.isNaN(parsedId) ? null : parsedId;
}

export async function GET(
  _request: Request,
  { params }: { params: Promise<Params> }
) {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post: PostRecord = {
    id: parsedId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<Params> }
) {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const updatedPost: PostRecord = {
    id: parsedId,
    title: body.title?.trim() || `Post ${id}`,
    content: body.content?.trim() || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(
  _request: Request,
  { params }: { params: Promise<Params> }
) {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json({ message: `Post ${id} deleted successfully` });
}

