import { cache } from 'react';

const JSON_PLACEHOLDER_BASE_URL = 'https://jsonplaceholder.typicode.com';

export type Post = {
  userId: number;
  id: number;
  title: string;
  body: string;
};

export type Comment = {
  postId: number;
  id: number;
  name: string;
  email: string;
  body: string;
};

async function fetchJson<T>(
  path: string,
  init?: RequestInit
): Promise<{ data: T; status: number }> {
  const response = await fetch(`${JSON_PLACEHOLDER_BASE_URL}${path}`, init);

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  const data = (await response.json()) as T;
  return { data, status: response.status };
}

export async function getRecentPosts(limit: number): Promise<Post[]> {
  const { data } = await fetchJson<Post[]>(`/posts?_limit=${limit}`, {
    cache: 'no-store',
  });
  return data;
}

export async function getAllPosts(revalidate: number): Promise<Post[]> {
  const { data } = await fetchJson<Post[]>('/posts', {
    next: { revalidate },
  });
  return data;
}

export const getPostById = cache(async (id: string): Promise<Post | null> => {
  const response = await fetch(`${JSON_PLACEHOLDER_BASE_URL}/posts/${id}`, {
    next: { revalidate: 300 },
  });

  if (response.status === 404) {
    return null;
  }

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  const post = (await response.json()) as Partial<Post>;

  if (typeof post.id !== 'number') {
    return null;
  }

  return post as Post;
});

export const getCommentsByPostId = cache(
  async (id: string): Promise<Comment[]> => {
    const { data } = await fetchJson<Comment[]>(`/posts/${id}/comments`, {
      next: { revalidate: 300 },
    });
    return data;
  }
);

